from typing import Protocol, runtime_checkable

@runtime_checkable
class SupportsRead(Protocol):
    def read(self, length: int = ...): ...

class Proxy:
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=0: b"data"
        raise AttributeError(name)

p = Proxy()
print(f"isinstance: {isinstance(p, SupportsRead)}")
print(f"hasattr: {hasattr(p, 'read')}")

